/* Default content-box -> renders 350px wide */
.card {
  width: 300px;
  padding: 20px;
  border: 5px solid #333;
}

/* Fix: include padding + border inside the 300px */
.card {
  box-sizing: border-box; /* renders exactly 300px */
}

/* Common project-wide reset */
*, *::before, *::after {
  box-sizing: border-box;
}

/* 1) Flexbox */
.parent { display: flex; justify-content: center; align-items: center; }

/* 2) Grid */
.parent { display: grid; place-items: center; }

/* 3) Absolute + transform */
.parent { position: relative; }
.box {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.layout { display: flex; }

/* Fixed sidebar: never grows or shrinks */
.sidebar { flex: 0 0 200px; }

/* Main fills the remaining space */
.main { flex: 1 1 0; min-width: 0; } /* min-width:0 lets it shrink below content */

.container {
  display: flex;
  flex-direction: column;
  height: 300px;
  justify-content: flex-end; /* main axis = vertical -> bottom */
  align-items: center;       /* cross axis = horizontal -> centered */
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

/* Swap to auto-fill if you want empty trailing tracks preserved:
   grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); */

.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header  header"
    "sidebar main"
    "footer  footer";
  min-height: 100vh;
  gap: 12px;
}
.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }
.footer  { grid-area: footer; }

.section-header {
  position: sticky;
  top: 0;        /* REQUIRED inset or it won't stick */
  background: #fff;
  z-index: 10;
}

/* Gotcha: this on any ancestor breaks stickiness */
.some-wrapper { overflow: hidden; } /* remove/change to overflow: visible */

/* Parent accidentally creates a stacking context via opacity */
.modal-wrapper {
  opacity: 0.99;     /* <- creates a stacking context, traps children */
  z-index: 1;
}
.modal { z-index: 9999; } /* only relative to .modal-wrapper */

.toast { position: relative; z-index: 2; } /* still wins vs the wrapper */

/* Fix: lift the parent's context, or drop opacity */
.modal-wrapper { opacity: 1; z-index: 10; }

/* Base = mobile: single column */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

/* Enhance for tablets and up */
@media (min-width: 768px) {
  .grid { grid-template-columns: 1fr 1fr; }
}

html { font-size: 16px; }

.child      { font-size: 1.5em; } /* 24px */
.grandchild {
  font-size: 1.5em;  /* 1.5 * 24 = 36px (compounds) */
  padding: 1em;      /* 1 * 36 = 36px */
}

.anywhere   { margin: 2rem; } /* 2 * 16 = 32px, no compounding */

.label.required::after {
  content: " *";       /* REQUIRED, or nothing renders */
  color: red;
  font-weight: bold;
}

/* Decorative-only example */
.icon::before {
  content: "";          /* still required, even if empty */
  display: inline-block;
  width: 16px; height: 16px;
  background: url('star.svg');
}

/* Single line */
.truncate {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Multi-line: clamp to 3 lines */
.clamp-3 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;          /* standard */
  overflow: hidden;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.spinner {
  width: 40px; height: 40px;
  border: 4px solid #ddd;
  border-top-color: #3498db;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

:root {
  --bg: #ffffff;
  --fg: #111111;
  --accent: #3498db;
}

.dark {
  --bg: #111111;
  --fg: #f5f5f5;
}

body {
  background: var(--bg);
  color: var(--fg);
}
.btn {
  /* fallback used only if --accent is undefined */
  background: var(--accent, #2980b9);
}

/* Correct: transition on the base selector */
.btn {
  background: #3498db;
  transition: background 200ms ease-in-out;
}
.btn:hover {
  background: #2c80b4;
}

/* Wrong: only animates hover-in, snaps back on hover-out
.btn:hover { transition: background 200ms; } */

.gone    { display: none; }       /* no space, no a11y, no events */
.hidden  { visibility: hidden; }   /* keeps space, no events, no a11y */
.transparent {
  opacity: 0;                      /* keeps space, STILL clickable + read */
  pointer-events: none;            /* add this to disable interaction */
}
